 INSERT INTO saas.subscriptions(id,store_id,plan_id,plan_code,plan_version,status,valid_from,created_at,updated_at) SELECT gen_random_uuid(),'21000000-0000-4000-8000-000000000003',id,plan_code,version,'active',clock_timestamp(),clock_timestamp(),clock_timestamp() FROM saas.plans WHERE plan_code='free_starter' AND version=1;
 CREATE FUNCTION saas.support_fixture_worker_complete(p_id uuid) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog AS $worker$ UPDATE saas.catalog_import_jobs SET status='completed',version=version+1,updated_at=clock_timestamp() WHERE id=p_id; $worker$;
 ALTER FUNCTION saas.support_fixture_worker_complete(uuid) OWNER TO celebix_saas_owner;
 REVOKE ALL ON FUNCTION saas.support_fixture_worker_complete(uuid) FROM PUBLIC;
 GRANT EXECUTE ON FUNCTION saas.support_fixture_worker_complete(uuid) TO celebix_saas_workflow;
 CREATE TEMP TABLE support_fixture_payload(value jsonb); INSERT INTO support_fixture_payload SELECT saas.platform_support_issue('21000000-0000-4000-8000-000000000002','21000000-0000-4000-8000-000000000003','support.admin.example.test','Investigate customer issue',1,'support.issue.fixture',repeat('a',64));
 DO $a$ DECLARE issued jsonb; resolved jsonb; redeemed jsonb; rejected boolean:=false; member uuid; plan uuid; outcome_value text; customer uuid:=gen_random_uuid(); BEGIN
 SELECT value INTO issued FROM support_fixture_payload;
 redeemed:=saas.platform_support_issue('21000000-0000-4000-8000-000000000002','21000000-0000-4000-8000-000000000003','support.admin.example.test','Investigate customer issue',1,'support.issue.fixture',repeat('a',64));
 IF redeemed->>'handoff'<>issued->>'handoff' OR redeemed->>'id'<>issued->>'id' OR (SELECT count(*) FROM saas.platform_support_sessions)<>1 THEN RAISE EXCEPTION 'ISSUE_RECOVERY_DIFFERENT_RESULT'; END IF;
 IF (issued->>'expiresAt')::timestamptz-(issued->>'issuedAt')::timestamptz<>interval '30 minutes' THEN RAISE EXCEPTION 'EXPIRY_WINDOW'; END IF;
 SELECT id INTO member FROM saas.memberships WHERE support_session_id=(issued->>'id')::uuid;
 IF saas.platform_membership_is_authorized(member) THEN RAISE EXCEPTION 'UNREDEEMED_AUTHORITY'; END IF;
 BEGIN PERFORM saas.platform_support_redeem(issued->>'handoff','foreign.example.test',repeat('c',64)); EXCEPTION WHEN raise_exception THEN rejected:=true; END; IF NOT rejected THEN RAISE EXCEPTION 'HOST_BYPASS'; END IF;
 redeemed:=saas.platform_support_redeem(issued->>'handoff','support.admin.example.test',repeat('c',64));
 resolved:=saas.platform_support_redeem(issued->>'handoff','support.admin.example.test',repeat('c',64));
 IF resolved->>'credential'<>redeemed->>'credential' OR resolved->>'id'<>redeemed->>'id' OR resolved->>'expiresAt'<>redeemed->>'expiresAt' OR resolved->>'replayed'<>'true' OR (SELECT count(*) FROM saas.platform_audit WHERE action='support.redeem')<>1 THEN RAISE EXCEPTION 'REDEEM_RECOVERY_DIFFERENT_RESULT'; END IF;
 IF EXISTS(SELECT 1 FROM saas.platform_support_sessions WHERE id=(issued->>'id')::uuid AND (handoff_hash=issued->>'handoff' OR credential_hash=redeemed->>'credential')) THEN RAISE EXCEPTION 'SUPPORT_PLAINTEXT_STORED'; END IF;
 rejected:=false;BEGIN PERFORM saas.platform_support_redeem(issued->>'handoff','support.admin.example.test',repeat('d',64)); EXCEPTION WHEN raise_exception THEN rejected:=true; END;IF NOT rejected THEN RAISE EXCEPTION 'HANDOFF_DIFFERENT_CREDENTIAL_ACCEPTED'; END IF;
 PERFORM set_config('role','celebix_saas_support_runtime',true);
 resolved:=saas.platform_support_resolve(redeemed->>'credential','support.admin.example.test','fixture');
 PERFORM set_config('role','none',true);
 IF resolved#>>'{tenantContext,principal,subject}'<>'verified-operator' OR resolved#>>'{tenantContext,membership,role}'<>'admin' OR resolved#>>'{tenantContext,entitlements,planCode}'<>'free_starter' OR resolved->'tenantContext' ? 'support' THEN RAISE EXCEPTION 'FAKE_OR_WIDENED_AUTHORITY'; END IF;
 IF EXISTS(SELECT 1 FROM saas.platform_normal_memberships WHERE id=member) OR (saas.platform_store_usage('21000000-0000-4000-8000-000000000003')->>'staff')::bigint<>0 THEN RAISE EXCEPTION 'SUPPORT_STAFF_LEAK'; END IF;
 SELECT plan_id INTO plan FROM saas.subscriptions WHERE store_id='21000000-0000-4000-8000-000000000003';
 INSERT INTO saas.customers(id,store_id,first_name,last_name,status,created_at,updated_at) VALUES(customer,'21000000-0000-4000-8000-000000000003','Fixture','Customer','active',clock_timestamp(),clock_timestamp());
 SELECT outcome INTO outcome_value FROM saas.customers_add_note('21000000-0000-4000-8000-000000000003','21000000-0000-4000-8000-000000000001',member,plan,'free_starter',1,clock_timestamp(),gen_random_uuid(),repeat('a',64),customer,gen_random_uuid(),'Support checked customer issue');
 IF outcome_value<>'committed' OR NOT EXISTS(SELECT 1 FROM saas.platform_support_write_journal WHERE session_id=(issued->>'id')::uuid AND table_name='customer_notes' AND operation='INSERT') OR NOT EXISTS(SELECT 1 FROM saas.platform_audit WHERE operator_id='21000000-0000-4000-8000-000000000002' AND action='support.write' AND payload->>'function'='customers_add_note') THEN RAISE EXCEPTION 'NATIVE_SUPPORT_WRITE_NOT_ATOMIC'; END IF;
 PERFORM saas.platform_support_begin('21000000-0000-4000-8000-000000000003','21000000-0000-4000-8000-000000000001',member,'fixture');
 UPDATE saas.stores SET name='Supported fixture',updated_at=clock_timestamp() WHERE id='21000000-0000-4000-8000-000000000003';
 IF NOT EXISTS(SELECT 1 FROM saas.platform_support_write_journal WHERE session_id=(issued->>'id')::uuid AND table_name='stores' AND operation='UPDATE') THEN RAISE EXCEPTION 'SUPPORT_WRITE_NOT_ATOMIC'; END IF;
 INSERT INTO saas.catalog_import_jobs(id,store_id,file_name,payload_digest,status,total_rows,succeeded_rows,failed_rows,version,created_at,updated_at) VALUES('21000000-0000-4000-8000-000000000010','21000000-0000-4000-8000-000000000003','fixture.csv',repeat('c',64),'processing',1,1,0,1,clock_timestamp(),clock_timestamp());
 PERFORM set_config('app.support_session_id','',true);
 PERFORM saas.platform_support_revoke('21000000-0000-4000-8000-000000000002',(issued->>'id')::uuid,1,'support.revoke.fixture');
 IF saas.platform_membership_is_authorized(member) OR saas.platform_support_resolve(redeemed->>'credential','support.admin.example.test','fixture') IS NOT NULL THEN RAISE EXCEPTION 'REVOKED_AUTHORITY'; END IF;
 rejected:=false;BEGIN PERFORM saas.platform_support_redeem(issued->>'handoff','support.admin.example.test',repeat('c',64));EXCEPTION WHEN raise_exception THEN rejected:=true;END;IF NOT rejected THEN RAISE EXCEPTION 'REDEEM_REPLAY_RESTORED_REVOKED_AUTHORITY'; END IF;
 PERFORM set_config('role','celebix_saas_workflow',true);
 PERFORM saas.support_fixture_worker_complete('21000000-0000-4000-8000-000000000010');
 PERFORM set_config('role','none',true);
 IF NOT EXISTS(SELECT 1 FROM saas.platform_support_write_journal WHERE session_id=(issued->>'id')::uuid AND table_name='catalog_import_jobs' AND operation='workflow:UPDATE' AND record_key->>'executingRole'='celebix_saas_workflow') OR NOT EXISTS(SELECT 1 FROM saas.platform_audit WHERE operator_id='21000000-0000-4000-8000-000000000002' AND action='support.workflow') THEN RAISE EXCEPTION 'ASYNC_INITIATOR_LOST_AFTER_REVOKE'; END IF;
 issued:=saas.platform_support_issue('21000000-0000-4000-8000-000000000002','21000000-0000-4000-8000-000000000003','support.admin.example.test','Expiry verification',1,'support.expiry.fixture',repeat('b',64));
 redeemed:=saas.platform_support_redeem(issued->>'handoff','support.admin.example.test',repeat('d',64));
 SELECT id INTO member FROM saas.memberships WHERE support_session_id=(issued->>'id')::uuid;
 UPDATE saas.platform_operators SET active=false WHERE id='21000000-0000-4000-8000-000000000002';
 IF saas.platform_membership_is_authorized(member) THEN RAISE EXCEPTION 'INACTIVE_OPERATOR_SUPPORT_AUTHORITY'; END IF;
 UPDATE saas.platform_operators SET active=true WHERE id='21000000-0000-4000-8000-000000000002';
 UPDATE saas.platform_support_sessions SET issued_at=statement_timestamp()-interval '31 minutes',expires_at=statement_timestamp()-interval '1 minute' WHERE id=(issued->>'id')::uuid;
 -- Set both timestamps from one value to preserve exact fixed session duration.
 UPDATE saas.platform_support_sessions SET expires_at=issued_at+interval '30 minutes' WHERE id=(issued->>'id')::uuid;
 IF saas.platform_membership_is_authorized(member) OR saas.platform_support_resolve(redeemed->>'credential','support.admin.example.test','fixture') IS NOT NULL OR NOT EXISTS(SELECT 1 FROM saas.memberships WHERE id=member AND status='active') THEN RAISE EXCEPTION 'EXPIRY_REQUIRES_CLEANUP'; END IF;
 rejected:=false;BEGIN PERFORM saas.platform_support_redeem(issued->>'handoff','support.admin.example.test',repeat('d',64));EXCEPTION WHEN raise_exception THEN rejected:=true;END;IF NOT rejected THEN RAISE EXCEPTION 'REDEEM_REPLAY_RESTORED_EXPIRED_AUTHORITY'; END IF;
 IF saas.merchant_action_authority_error('21000000-0000-4000-8000-000000000003','21000000-0000-4000-8000-000000000001',member,plan,'free_starter',1,now()-interval '1 hour','customers','customers.manage')<>'membership_denied' THEN RAISE EXCEPTION 'STALE_TIME_RESTORES_SUPPORT'; END IF;
 rejected:=false;BEGIN PERFORM saas.customers_add_note('21000000-0000-4000-8000-000000000003','21000000-0000-4000-8000-000000000001',member,plan,'free_starter',1,clock_timestamp(),gen_random_uuid(),repeat('b',64),customer,gen_random_uuid(),'Expired support must not write');EXCEPTION WHEN raise_exception THEN rejected:=true;END;IF NOT rejected OR (SELECT count(*) FROM saas.customer_notes WHERE customer_id=customer)<>1 THEN RAISE EXCEPTION 'EXPIRED_NATIVE_WRITE'; END IF;
 PERFORM saas.platform_sales_policy_set('21000000-0000-4000-8000-000000000002','21000000-0000-4000-8000-000000000003',true,'Temporarily paused',1,'sales.pause.fixture');
 IF saas.platform_new_sales_allowed('21000000-0000-4000-8000-000000000003') OR saas.platform_sales_policy_get('21000000-0000-4000-8000-000000000002','21000000-0000-4000-8000-000000000003')->>'newSalesEnabled'<>'false' OR saas.platform_sales_policy_get('21000000-0000-4000-8000-000000000002','21000000-0000-4000-8000-000000000003')->>'changedBy'<>'21000000-0000-4000-8000-000000000002' THEN RAISE EXCEPTION 'PAUSE_IGNORED'; END IF;
 IF NOT saas.platform_new_sales_allowed('10000000-0000-4000-8000-000000000148') THEN RAISE EXCEPTION 'FOREIGN_POLICY_LEAK'; END IF;
 rejected:=false;BEGIN PERFORM saas.platform_sales_policy_set('21000000-0000-4000-8000-000000000002','21000000-0000-4000-8000-000000000003',false,'Temporarily resumed',1,'sales.resume.fixture');EXCEPTION WHEN raise_exception THEN rejected:=true;END;IF NOT rejected THEN RAISE EXCEPTION 'STALE_POLICY_VERSION';END IF;
 PERFORM saas.platform_sales_policy_set('21000000-0000-4000-8000-000000000002','21000000-0000-4000-8000-000000000003',true,'Temporarily paused',1,'sales.pause.fixture');
 PERFORM saas.platform_sales_policy_set('21000000-0000-4000-8000-000000000002','21000000-0000-4000-8000-000000000003',false,'Temporarily resumed',2,'sales.resume.fixture');
 IF NOT saas.platform_new_sales_allowed('21000000-0000-4000-8000-000000000003') THEN RAISE EXCEPTION 'RESUME_IGNORED'; END IF;
 END $a$; ROLLBACK;
